$authorsArray = explode(", ", $authorsList);

// Step 2: Normalize the author names (convert to lowercase, trim spaces, etc.)
$normalizedAuthors = array_map('strtolower', $authorsArray);

// Step 3: Remove duplicates by using array_unique()
$uniqueAuthors = array_unique($normalizedAuthors);

// Step 4: Fuzzy match and group similar names
$groupedAuthors = [];
foreach ($uniqueAuthors as $author) {
    $found = false;
    // Check each author against the already grouped authors
    foreach ($groupedAuthors as &$group) {
        // If the author is similar to any name in the group, add them to the group
        similar_text($author, $group[0], $percent);
        if ($percent > 80) { // Adjust the threshold for similarity
            $group[] = $author;
            $found = true;
            break;
        }
    }
    // If no similar group is found, create a new group
    if (!$found) {
        $groupedAuthors[] = [$author];
    }
}

// Flatten the groups and get the unique authors
$uniqueAuthors = [];
foreach ($groupedAuthors as $group) {
    $uniqueAuthors[] = $group[0]; // Consider only the first name in each group
}

// Step 5: Count the unique authors
$uniqueAuthorCount = count($uniqueAuthors);

// Output the count of unique authors
echo "Number of unique authors: " . $uniqueAuthorCount . "\n";

